task.vi:
Tìm lỗi trong mỗi đoạn chương trình sau đây. Giả sử đã khai báo sẵn:
  int *zPtr;
  int *aPtr = NULL;
  void *sPtr = NULL;
  int number;
  int z[5] = {1, 2, 3, 4, 5};
  sPtr = z;

a) ++zPtr;
b) // Dùng con trỏ để lấy giá trị đầu tiên của mảng; giả sử zPtr đã được khởi tạo
   number = zPtr;
c) // Gán phần tử mảng index 2 (giá trị 3) cho number; giả sử zPtr đã được khởi tạo
   number = *zPtr[2];
d) // In toàn bộ mảng z; giả sử zPtr đã được khởi tạo
   for (size_t i = 0; i <= 5; ++i) {
       printf("%d ", zPtr[i]);
   }
e) // Gán giá trị được trỏ bởi sPtr cho number
   number = *sPtr;
f) ++z;

task.en:
Find the error in each of the following program segments. Assume:
  int *zPtr;
  int *aPtr = NULL;
  void *sPtr = NULL;
  int number;
  int z[5] = {1, 2, 3, 4, 5};
  sPtr = z;

a) ++zPtr;
b) // use pointer to get first value of array; assume zPtr is initialized
   number = zPtr;
c) // assign array element 2 (the value 3) to number; assume zPtr is initialized
   number = *zPtr[2];
d) // print entire array z; assume zPtr is initialized
   for (size_t i = 0; i <= 5; ++i) {
       printf("%d ", zPtr[i]);
   }
e) // assign the value pointed to by sPtr to number
   number = *sPtr;
f) ++z;

