#include <iostream>

void doubleValue(int* ptr) {
    if (ptr != nullptr) {
        *ptr *= 2;
    }
}

void displayReadOnly(const int* ptr) {
    if (ptr != nullptr) {
        std::cout << "Value: " << *ptr << "\n";
    }
}

int main() {
    int num = 25;
    int* numPtr = &num;

    displayReadOnly(numPtr);
    doubleValue(numPtr);
    displayReadOnly(numPtr);

    // Const pointer to non-const data
    int anotherNum = 100;
    int* const lockedPtr = &anotherNum;
    *lockedPtr = 150;
    std::cout << "Locked pointer value: " << *lockedPtr << "\n";

    return 0;
}

#include <iostream>

int square(int x) {
    return x * x;
}

int cube(int x) {
    return x * x * x;
}

// Function taking a function pointer
int compute(int val, int (*operation)(int)) {
    return operation(val);
}

int main() {
    int nums[5] = {10, 20, 30, 40, 50};
    int* ptr = nums;

    // Array-pointer notations
    std::cout << "Array index: " << nums[2] << "\n";
    std::cout << "Pointer offset: " << *(ptr + 2) << "\n";
    std::cout << "Pointer index: " << ptr[2] << "\n";

    // Pointer subtraction (distance in elements)
    int* endPtr = &nums[4];
    std::cout << "Distance: " << (endPtr - ptr) << "\n";

    // Function pointer dispatch
    int (*func)(int) = square;
    std::cout << "Square(4): " << compute(4, func) << "\n";
    func = cube;
    std::cout << "Cube(4): " << compute(4, func) << "\n";

    return 0;
}
